TRIPLES = [
    {"head": "分布式表示", "relation": "相关概念", "tail": "One-hot编码"},
    {"head": "分布式表示", "relation": "容易混淆", "tail": "One-hot编码"},
    {"head": "词嵌入", "relation": "相关概念", "tail": "分布式表示"},
    {"head": "词嵌入", "relation": "相关概念", "tail": "分布式表示"},
]


class KnowledgeGraph:
    def __init__(self, triples=None):
        self.triples = []
        self.edges = []
        seen = set()
        for triple in triples if triples is not None else TRIPLES:
            key = (triple["head"], triple["relation"], triple["tail"])
            if key in seen:
                continue
            seen.add(key)
            self.triples.append(
                {"head": key[0], "relation": key[1], "tail": key[2]}
            )
            self.edges.append(key)

    def get_neighbors(self, entity):
        found = []
        for head, relation, tail in self.edges:
            if entity in (head, tail):
                found.append({"head": head, "relation": relation, "tail": tail})
        return found
